#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <limits.h>

int main()
{
    int n, i, t, tfin, min, changes;
    int *a;

    scanf("%d", &n);
    a = (int*)calloc(n, sizeof(int));
    for(i = 0; i < n; i++)
        scanf("%d", &a[i]);

    changes = 0;
    tfin = 0;
    min = INT_MAX;
    for(t = 1; t < 100; t++)
    {
        for(i = 0; i < n; i++)
            if(a[i] > t)
            {
                if(abs(a[i] - t) > 1)
                    changes += abs(a[i] - (t + 1));
            }
            else
            {
                if(abs(t - a[i]) > 1)
                    changes += abs((t - 1) - a[i]);
            }

        if(changes < min)
        {
            min = changes;
            tfin = t;
        }
        changes = 0;
    }
    printf("%d %d", tfin, min);
    return 0;
}

