    let mut tfin = 0;
    let mut min = i32::MAX;

    for t in 1..100 {
        for &value in &a {
            if value > t {
                if (value - t).abs() > 1 {
                    changes += (value - (t + 1)).abs();
                }
            } else {
                if (t - value).abs() > 1 {
                    changes += ((t - 1) - value).abs();
                }
            }
        }

        if changes < min {
            min = changes;
            tfin = t;
        }
        changes = 0;
    }

    println!("{} {}", tfin, min);
}

