#include <stdio.h>
#include <stdlib.h>

#define SWAP(x, y, T) do { T SWAP = x; x = y; y = SWAP; } while (0)

int main(void){
    int t, n, l, r, c, *cl, *cr, count, min;
    scanf("%i", &t);
    for (t; t; t--){
        count = 0;
        scanf("%i %i %i", &n, &l, &r);
        cl = (int *) calloc(n, sizeof(int));
        cr = (int *) calloc(n, sizeof(int));
        for (int i = 0; i < l; i++){
            scanf("%i", &c);
            cl[c - 1]++;
        }
        for (int i = 0; i < r; i++){
            scanf("%i", &c);
            cr[c - 1]++;
        }
        for (int i = 0; i < n; i++)
            if (cl[i] && cr[i]){
                min = cl[i] < cr[i]? cl[i]: cr[i];
                cl[i] -= min;
                cr[i] -= min;
                l -= min;
                r -= min;
            }
        if (l < r){
            SWAP(cl, cr, int *);
            SWAP(l, r, int);
        }
        for (int i = 0; i < n; i++){
            c = cl[i] - cl[i] % 2;
            min = (l - r) < c? l - r: c;
            count += min / 2;
            l -= min;
        }
        count += l;
        printf("%i\n", count);
        free(cl);
        free(cr);
    }
    return 0;
}

