        let n: usize = parts.next().unwrap().parse().unwrap();
        let mut l: usize = parts.next().unwrap().parse().unwrap();
        let mut r: usize = parts.next().unwrap().parse().unwrap();
        let mut cl = vec![0; n];
        let mut cr = vec![0; n];
        for _ in 0..l {
            let c: usize = lines.next().unwrap().unwrap().parse().unwrap();
            cl[c - 1] += 1;
        }
        for _ in 0..r {
            let c: usize = lines.next().unwrap().unwrap().parse().unwrap();
            cr[c - 1] += 1;
        }
        for i in 0..n {
            if cl[i] > 0 && cr[i] > 0 {
                let min = cl[i].min(cr[i]);
                cl[i] -= min;
                cr[i] -= min;
                l -= min;
                r -= min;
            }
        }
        if l < r {
            std::mem::swap(&mut cl, &mut cr);
            std::mem::swap(&mut l, &mut r);
        }
        let mut count = 0;
        for i in 0..n {
            let c = cl[i] - cl[i] % 2;
            let min = (l - r).min(c);
            count += min / 2;
            l -= min;
        }
        count += l;
        println!("{}", count);
    }
}

