use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());

    let first_line: Vec<f32> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();
    let a = first_line[0];
    let b = first_line[1];

    let n: usize = lines.next().unwrap().parse().unwrap();

    let mut cab: Vec<Vec<f32>> = Vec::with_capacity(n);
    for _ in 0..n {
        let line: Vec<f32> = lines.next().unwrap().split_whitespace()
            .map(|s| s.parse().unwrap())
            .collect();
        cab.push(line);
    }

    let mut tim: Vec<f32> = Vec::with_capacity(n);
    for entry in &cab {
        let x = entry[0] - a;
        let y = entry[1] - b;
        tim.push((x * x + y * y).sqrt() / entry[2]);
    }

    let min = tim.iter().cloned().fold(f32::INFINITY, f32::min);
    println!("{}", min);
}

