fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;

    let mut lines = input.lines();
    let mut first_line = lines.next().unwrap().split_whitespace();
    let n: usize = first_line.next().unwrap().parse().unwrap();
    let m: usize = first_line.next().unwrap().parse().unwrap();

    let mut res = vec![b' '; n];
    let mut a = vec![vec![0; m]; n];

    for (i, line) in lines.enumerate().take(n) {
        for (j, ch) in line.chars().enumerate().take(m) {
            a[i][j] = ch.to_digit(10).unwrap() as i32;
        }
    }

    for i in 0..m {
        let mut max = a[0][i];
        for j in 0..n {
            if max < a[j][i] {
                max = a[j][i];
            }
        }

        for j in 0..n {
            if max == a[j][i] {
                res[j] = b'#';
            }
        }
    }

    let ans = res.iter().filter(|&&ch| ch == b'#').count();
    println!("{}", ans);

    Ok(())
}

