fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let s = input.trim();
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let k: usize = input.trim().parse().unwrap();

    if s.len() % k != 0 {
        writeln!(io::stdout(), "NO")?;
        return Ok(());
    }

    let segment_length = s.len() / k;
    for segment in s.as_bytes().chunks(segment_length) {
        if !is_palindrome(segment) {
            writeln!(io::stdout(), "NO")?;
            return Ok(());
        }
    }

    writeln!(io::stdout(), "YES")?;
    Ok(())
}

fn is_palindrome(bytes: &[u8]) -> bool {
    bytes.iter().zip(bytes.iter().rev()).all(|(a, b)| a == b)
}

