use std::io::{self, Write, BufRead, BufReader};

fn main() -> io::Result<()> {
    let fa = File::open("input.txt")?;
    let fb = File::create("output.txt")?;
    let mut reader = BufReader::new(fa);
    let mut writer = fb;

    let mut line = String::new();
    reader.read_line(&mut line)?;

    let parts: Vec<&str> = line.split_whitespace().collect();
    let a: i32 = parts[0].parse().unwrap();
    let b: i32 = parts[1].parse().unwrap();

    let mut result = String::new();
    if a > b {
        result.extend(std::iter::repeat("BG").take(b as usize));
        result.extend(std::iter::repeat("B").take((a - b) as usize));
    } else {
        result.extend(std::iter::repeat("GB").take(a as usize));
        result.extend(std::iter::repeat("G").take((b - a) as usize));
    }
    result.push('\n');

    writer.write_all(result.as_bytes())?;

    Ok(())
}

