    let first_line: Vec<usize> = lines.next().unwrap().split_whitespace()
        .map(|s| s.parse().unwrap()).collect();
    let (n, c) = (first_line[0], first_line[1]);

    let mut ll = vec![0; n];
    let mut ww = Vec::with_capacity(n);
    for (i, line) in lines.take(n).enumerate() {
        let mut parts = line.split_whitespace();
        ll[i] = parts.next().unwrap().parse().unwrap();
        ww.push(parts.map(|s| s.parse::<usize>().unwrap() - 1).collect::<Vec<_>>());
