    for i in 0..n - 1 {
        let l = ll[i].min(ll[i + 1]);
        let mut found_diff = false;
        for j in 0..l {
            if ww[i][j] != ww[i + 1][j] {
                let a = (c - ww[i][j]) % c;
                let b = c - 1 - ww[i + 1][j];
                if a <= b {
                    dd[a] += 1;
                    dd[b + 1] -= 1;
                } else {
                    dd[a] += 1;
                    dd[0] += 1;
                    dd[b + 1] -= 1;
