        let line = lines.next().unwrap().unwrap();
        if line.len() > 1 && line[1..].contains(|c: char| c.is_digit(10)) && line.contains('C') {
            let c_ind = line.find('C').unwrap();
            let row: isize = line[1..c_ind].parse().unwrap();
            let col: isize = line[c_ind + 1..].parse().unwrap();
            let mut col_sub = String::new();
            let mut col = col;
            while col > 0 {
                let remainder = (col - 1) % 26;
                col_sub.push((b'A' + remainder as u8) as char);
                col = (col - 1) / 26;
            }
            col_sub = col_sub.chars().rev().collect();
            println!("{}{}", col_sub, row);
        } else {
            let row_ind = line.find(|c: char| c.is_digit(10)).unwrap();
            let mut col = 0;
            for (j, c) in line[..row_ind].chars().enumerate() {
                col += (c as isize - b'A' as isize + 1) * 26_isize.pow((row_ind - j - 1) as u32);
            }
            let row: isize = line[row_ind..].parse().unwrap();
            println!("R{}C{}", row, col);
        }
    }
}

