    for row in aa.iter_mut() {
        let input = lines.next().unwrap().unwrap();
        let values: Vec<f64> = input.split_whitespace()
                                  .map(|s| s.parse().unwrap())
                                  .collect();
        row.copy_from_slice(&values);
    }

    ff[0] = 1.0;
    for a in 1..(1 << n) {
        let cnt0 = (0..n).filter(|&i| a & (1 << i) == 0).count();
        for i in 0..n {
            if a & (1 << i) > 0 {
                for j in 0..n {
                    if a & (1 << j) == 0 {
                        ff[a] += ff[a - (1 << i)] * aa[j][i];
                    }
                }
            }
        }
        ff[a] /= (cnt0 + 1) as f64 * cnt0 as f64 / 2.0;
    }

    for i in 0..n {
        print!("{:.6} ", ff[(1 << n) - 1 - (1 << i)]);
    }
    println!();
}

