        for (i, road) in roads.iter_mut().enumerate() {
            if road.a == a && !used[i] {
                next = Some((road.b, i));
                break;
            }
        }
        if let Some((b, i)) = next {
            used[i] = true;
            a = b;
        } else {
            let mut found = false;
