use std::fs::File;
use std::io::{self, BufRead, BufReader, Write};

fn main() -> io::Result<()> {
    let p1 = File::open("input.txt")?;
    let p2 = File::create("output.txt")?;
    let reader = BufReader::new(p1);
    let mut writer = p2;

    for line in reader.lines() {
        let line = line?;
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() != 2 {
            continue;
        }

        let n: i32 = parts[0].parse().unwrap_or(0);
        let m: i32 = parts[1].parse().unwrap_or(0);

        if m >= n {
            for _ in 0..n {
                writer.write_all(b"GB")?;
            }
            for _ in 0..(m - n) {
                writer.write_all(b"G")?;
            }
        } else {
            for _ in 0..m {
                writer.write_all(b"BG")?;
            }
            for _ in 0..(n - m) {
                writer.write_all(b"B")?;
            }
        }
    }

    Ok(())
}

