    let mut ball1 = 0;
    let mut ball2 = 0;
    let mut set1 = false;

    for line in reader.lines() {
        let line = line?;
        if line.is_empty() {
            if ball1 == ball {
                ball = ball2;
            } else if ball2 == ball {
                ball = ball1;
            }
            set1 = false;
        } else {
            let mut chars = line.chars().filter(|c| !c.is_whitespace());
            if !set1 {
                if let Some(c) = chars.next() {
                    ball1 = c.to_digit(10).unwrap() as i32;
                    set1 = true;
                }
            }
            if let Some(c) = chars.next() {
                ball2 = c.to_digit(10).unwrap() as i32;
            }
        }
    }

    let mut output_file = File::create("output.txt")?;
    write!(output_file, "{}", ball)?;

    Ok(())
}

