	int i, n, a, sum, cost;
	char *used;

	scanf("%d", &n);
	rr = malloc(n * sizeof(*rr));
	used = calloc(n, sizeof(*used));
	sum = cost = 0;
	for (i = 0; i < n; i++) {
		scanf("%d%d%d", &rr[i].a, &rr[i].b, &rr[i].c);
		sum += rr[i].c;
	}

	a = 1;

	do {
		int tmp, next; 

		for (i = 0; i < n; i++)
			if (rr[i].a == a && !used[i]) {
				next = rr[i].b;
				used[i] = 1;
				break;
			}
		if (i == n)
			for (i = 0; i < n; i++)
				if (rr[i].b == a && !used[i]) {
					tmp = rr[i].a, rr[i].a = rr[i].b, rr[i].b = tmp;
					cost += rr[i].c;
					next = rr[i].b;
					used[i] = 1;
					break;
				}
		a = next;
	} while (a != 1);
	printf("%d\n", cost < sum - cost ? cost : sum - cost);
