use std::io::{self, BufRead};

struct Road {
    a: i32,
    b: i32,
    c: i32,
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let n: usize = lines.next().unwrap().unwrap().parse().unwrap();
    let mut roads: Vec<Road> = Vec::with_capacity(n);
    let mut sum = 0;

    for _ in 0..n {
        let line = lines.next().unwrap().unwrap();
        let parts: Vec<i32> = line.split_whitespace().map(|s| s.parse().unwrap()).collect();
        let road = Road {
            a: parts[0],
            b: parts[1],
            c: parts[2],
        };
        sum += road.c;
        roads.push(road);
    }

    let mut used = vec![false; n];
    let mut cost = 0;
    let mut a = 1;

    loop {
        let mut next = None;

        for (i, road) in roads.iter().enumerate() {
            if road.a == a && !used[i] {
                next = Some((road.b, i));
                break;
            }
        }

        if let Some((b, i)) = next {
            used[i] = true;
            a = b;
        } else {
            for (i, road) in roads.iter().enumerate() {
                if road.b == a && !used[i] {
                    cost += road.c;
                    used[i] = true;
                    a = road.a;
                    break;
                }
            }
        }

        if a == 1 {
            break;
        }
    }

    println!("{}", cost.min(sum - cost));
}

