use std::collections::VecDeque;

struct House {
    x: i32,
    a: i32,
    prev: Option<usize>,
    next: Option<usize>,
}

struct Houses {
    houses: VecDeque<House>,
}

impl Houses {
    fn new() -> Self {
        let mut houses = VecDeque::new();
        let first = House { x: i32::MIN, a: 0, prev: None, next: Some(1) };
        let last = House { x: i32::MAX, a: 0, prev: Some(0), next: None };
        houses.push_back(first);
        houses.push_back(last);
        Houses { houses }
    }

    fn insert(&mut self, x: i32, a: i32) {
        let new_house = House { x, a, prev: None, next: None };
        let mut idx = 1;
        while self.houses[idx].x < x {
            idx = self.houses[idx].next.unwrap();
        }
        let prev_idx = self.houses[idx].prev.unwrap();
        self.houses[idx].prev = Some(self.houses.len());
        self.houses[prev_idx].next = Some(self.houses.len());
        self.houses.push_back(new_house);
    }

    fn calculate_possible(&self, t: i32) -> u64 {
        let mut possible = 0;
        let mut idx = 1;
        while let Some(next_idx) = self.houses[idx].next {
            if next_idx == self.houses.len() - 1 {
                break;
            }
            let delta2x = 2 * (self.houses[next_idx].x - self.houses[idx].x) - self.houses[idx].a - self.houses[next_idx].a;
            possible += match delta2x.cmp(&(2 * t)) {
                std::cmp::Ordering::Less => 0,
                std::cmp::Ordering::Equal => 1,
                std::cmp::Ordering::Greater => 2,
            };
            idx = next_idx;
        }
        possible + 2
    }
}

fn main() {
    let mut houses = Houses::new();
    let (n, t) = {
        let mut input = String::new();
        std::io::stdin().read_line(&mut input).unwrap();
        let mut iter = input.split_whitespace().map(|s| s.parse().unwrap());
        (iter.next().unwrap(), iter.next().unwrap())
    };
    for _ in 0..n {
        let (x, a) = {
            let mut input = String::new();
            std::io::stdin().read_line(&mut input).unwrap();
            let mut iter = input.split_whitespace().map(|s| s.parse().unwrap());
            (iter.next().unwrap(), iter.next().unwrap())
        };
        houses.insert(x, a);
    }
    println!("{}", houses.calculate_possible(t));
}

