const MAXS: usize = 200_001;

fn cval(c: char) -> u32 {
    (c as u32) - ('a' as u32) + 1
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let t: usize = lines.next().unwrap().unwrap().parse().unwrap();

    let mut buffer = String::with_capacity(MAXS);

    for _ in 0..t {
        buffer.clear();
        lines.next().unwrap().unwrap().chars().take_while(|&c| c != '\n').for_each(|c| buffer.push(c));
        let s = buffer.as_bytes();

        let len = s.len();
        if len == 1 {
            println!("Bob {}", cval(s[0] as char));
        } else if len == 2 {
            println!("Alice {}", cval(s[0] as char) + cval(s[1] as char));
        } else {
            let sum: u32 = s.iter().map(|&c| cval(c as char)).sum();
            let min = if len % 2 == 1 {
                std::cmp::min(cval(s[0] as char), cval(s[len - 1] as char))
            } else {
                0
            };
            println!("Alice {}", sum - min - min);
        }
    }
}

