use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let path = lines.next().unwrap().unwrap();
    let fr = lines.next().unwrap().unwrap();
    let sc = lines.next().unwrap().unwrap();

    let forward = path.find(&fr).and_then(|start| {
        path[start + fr.len()..].find(&sc).map(|end| start + fr.len() + end)
    });

    let mut path_chars: Vec<char> = path.chars().collect();
    path_chars.reverse();
    let reversed_path: String = path_chars.into_iter().collect();

    let backward = reversed_path.find(&fr).and_then(|start| {
        reversed_path[start + fr.len()..].find(&sc).map(|end| start + fr.len() + end)
    });

    match (forward, backward) {
        (Some(_), Some(_)) => println!("both"),
        (Some(_), None) => println!("forward"),
        (None, Some(_)) => println!("backward"),
        (None, None) => println!("fantasy"),
    }
}

