        std::io::stdin().read_line(&mut input).unwrap();
        parts = input.split_whitespace();
        for i in 1..=n {
            b[i] = parts.next().unwrap().parse().unwrap();
            ex.insert(b[i], i);
            if a[i] != b[i] {
                if need[b[i]] == 0 {
                    tot += 1;
                }
                need[b[i]] += 1;
                loc[b[i]].push(i);
            }
