            if need[c[i]] > 0 {
                ans[i] = loc[c[i]].pop().unwrap();
                need[c[i]] -= 1;
                if need[c[i]] == 0 {
                    tot -= 1;
                }
            } else {
                if last == 0 {
                    if let Some(&index) = ex.get(&c[i]) {
                        ans[i] = index;
