                        flag = false;
                        break;
                    }
                } else {
                    ans[i] = last;
                }
            }
            last = ans[i];
        }

        if flag && tot > 0 {
            println!("NO");
        } else if flag {
            println!("YES");
            for i in 1..=m {
                print!("{} ", ans[i]);
            }
            println!();
        }

        t -= 1;
    }
}

