use std::io::{self, BufRead};

struct Walrus {
    pos: usize,
    sig: Option<Box<Walrus>>,
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.unwrap());
    let n: usize = lines.next().unwrap().parse().unwrap();
    let edad: Vec<i32> = lines.next().unwrap().split_whitespace()
        .take(n)
        .map(|s| s.parse().unwrap())
        .collect();
    let mut enojo = vec![-1; n];
    let mut sig = Some(Box::new(Walrus { pos: n - 1, sig: None }));

    for i in (0..n).rev() {
        if edad[i] > edad[sig.as_ref().unwrap().pos] {
            let mut aux = &sig;
            while let Some(node) = aux {
                if edad[i] > edad[node.pos] {
                    enojo[i] = node.pos as i32 - i as i32 - 1;
                    aux = &node.sig;
                } else {
                    break;
                }
            }
        } else if edad[i] < edad[sig.as_ref().unwrap().pos] {
            let nuevo = Box::new(Walrus { pos: i, sig: sig.take() });
            sig = Some(nuevo);
        }
    }

    for e in enojo {
        print!("{} ", e);
    }
    println!();
}

