    while boys > 0 || girls > 0 {
        if boys > 0 {
            output.push('B');
            boys -= 1;
        }
        if girls > 0 {
            output.push('G');
            girls -= 1;
        }
    }

    writer.write_all(output.as_bytes())?;
    Ok(())
}

